tasks.starter:
const planets = ["Merkür", "Venüs", "Dünya", "Mars"];

// first, last ve count'u oluştur

console.log(first, last, count);

tasks.solution:
const planets = ["Merkür", "Venüs", "Dünya", "Mars"];

// first, last ve count'u oluştur
const first = planets[0];
const last = planets[planets.length - 1];
const count = planets.length;

console.log(first, last, count);

check.js:
assert(first === "Merkür", "first 'Merkür' olmalı.");
assert(last === "Mars", "last 'Mars' olmalı.");
assert(count === 4, "count 4 olmalı.");
assert(/length\s*-\s*1/.test(_code), "Son elemana planets[planets.length - 1] ile ulaş.");
assert((_code.match(/["'`]Mars["'`]/g) || []).length === 1, "\"Mars\" metnini ikinci kez yazma; diziden al.");

tasks.starter:
const cargo = ["yakıt", "su", "çöp"];

// pop, push ve unshift ile düzenle

console.log(cargo);

tasks.solution:
const cargo = ["yakıt", "su", "çöp"];

// pop, push ve unshift ile düzenle
cargo.pop();
cargo.push("kalkan");
cargo.unshift("harita");

console.log(cargo);

check.js:
assert(/cargo\s*=\s*\[\s*["'`]yakıt["'`]\s*,\s*["'`]su["'`]\s*,\s*["'`]çöp["'`]\s*\]/.test(_code), "Dizinin ilk satırını değiştirme: const cargo = [\"yakıt\", \"su\", \"çöp\"];");
assert(same(cargo, ["harita", "yakıt", "su", "kalkan"]), "cargo sonunda ['harita', 'yakıt', 'su', 'kalkan'] olmalı.");
assert(/\.pop\s*\(/.test(_code) && /\.push\s*\(/.test(_code) && /\.unshift\s*\(/.test(_code), "pop, push ve unshift metotlarını kullanmalısın.");

