challenge.starter:
const route = ["Dünya", "Ay", "Mars", "Jüpiter"];

// 1) splice ile ekle
// 2) firstStops
// 3) routeText

console.log(firstStops);
console.log(routeText);

challenge.solution:
const route = ["Dünya", "Ay", "Mars", "Jüpiter"];

// 1) splice ile ekle
route.splice(3, 0, "Asteroit Kuşağı");
// 2) firstStops
const firstStops = route.slice(0, 2);
// 3) routeText
const routeText = route.join(" → ");

console.log(firstStops);
console.log(routeText);

check.js:
assert(!/["'`]Mars["'`]\s*,\s*["'`]Asteroit/.test(_code), "Dizinin ilk satırını değiştirme; yeni durağı splice ile ekle.");
assert(same(route, ["Dünya", "Ay", "Mars", "Asteroit Kuşağı", "Jüpiter"]), "route sonunda ['Dünya', 'Ay', 'Mars', 'Asteroit Kuşağı', 'Jüpiter'] olmalı.");
assert(same(firstStops, ["Dünya", "Ay"]), "firstStops ['Dünya', 'Ay'] olmalı.");
assert(routeText === "Dünya → Ay → Mars → Asteroit Kuşağı → Jüpiter", "routeText 'Dünya → Ay → Mars → Asteroit Kuşağı → Jüpiter' olmalı.");
assert(/\.splice\s*\(/.test(_code) && /\.join\s*\(/.test(_code), "splice ve join kullanmalısın.");

project_task.starter:
const inventory = ["kalkan", "lazer"];

// 1) yakıt hücresi ekle
// 2) lazeri çıkar
// 3) hasShield
// 4) Envanter satırını yazdır

project_task.solution:
const inventory = ["kalkan", "lazer"];

// 1) yakıt hücresi ekle
inventory.push("yakıt hücresi");
// 2) lazeri çıkar
const laserIndex = inventory.indexOf("lazer");
inventory.splice(laserIndex, 1);
// 3) hasShield
const hasShield = inventory.includes("kalkan");
// 4) Envanter satırını yazdır
console.log(`Envanter: ${inventory.join(", ")} (${inventory.length} eşya)`);

check.js:
assert(same(inventory, ["kalkan", "yakıt hücresi"]), "inventory sonunda ['kalkan', 'yakıt hücresi'] olmalı.");
assert(hasShield === true, "hasShield true olmalı.");
assert(/\.splice\s*\(/.test(_code), "Lazeri splice ile çıkarmalısın.");
assert(_lines.includes("Envanter: kalkan, yakıt hücresi (2 eşya)"), "Çıktıda 'Envanter: kalkan, yakıt hücresi (2 eşya)' görünmeli.");
assert(!/kalkan, yakıt/.test(_code) && !/\(2 eşya/.test(_code), "Satırı elle yazma; join ve length kullan.");

project_task.starter:
const menu = ["Ana Sayfa", "Hakkımda", "Projeler"];

// 1) İletişim'i ekle
// 2) menuCount
// 3) hasBlog
// 4) menuText'i oluştur ve yazdır

project_task.solution:
const menu = ["Ana Sayfa", "Hakkımda", "Projeler"];

// 1) İletişim'i ekle
menu.push("İletişim");
// 2) menuCount
