// 4) menuText'i oluştur ve yazdır
const menuText = menu.join(" | ");
console.log(menuText);

check.js:
assert(same(menu, ["Ana Sayfa", "Hakkımda", "Projeler", "İletişim"]), "menu sonunda ['Ana Sayfa', 'Hakkımda', 'Projeler', 'İletişim'] olmalı.");
assert(menuCount === 4, "menuCount 4 olmalı.");
assert(hasBlog === false, "hasBlog false olmalı (menüde Blog yok).");
assert(menuText === "Ana Sayfa | Hakkımda | Projeler | İletişim", "menuText 'Ana Sayfa | Hakkımda | Projeler | İletişim' olmalı.");
assert(_lines.includes(menuText), "menuText'i yazdırmalısın.");
assert(!/Ana Sayfa \|/.test(_code), "Menü metnini elle yazma; join kullan.");

project_task.starter:
const tasks = ["Matematik ödevi", "Kitap okuma"];

// 1) yeni görevi ekle
// 2) finished
// 3) iki satırı yazdır

project_task.solution:
const tasks = ["Matematik ödevi", "Kitap okuma"];

// 1) yeni görevi ekle
tasks.push("İngilizce kelime");
// 2) finished
const finished = tasks.shift();
// 3) iki satırı yazdır
console.log("Tamamlandı:", finished);
console.log("Kalan görev:", tasks.length);

check.js:
assert(finished === "Matematik ödevi", "finished 'Matematik ödevi' olmalı.");
assert(same(tasks, ["Kitap okuma", "İngilizce kelime"]), "tasks sonunda ['Kitap okuma', 'İngilizce kelime'] olmalı.");
assert(_lines.includes("Tamamlandı: Matematik ödevi") && _lines.includes("Kalan görev: 2"), "Çıktıda 'Tamamlandı: Matematik ödevi' ve 'Kalan görev: 2' görünmeli.");
assert(!/Tamamlandı: Matematik/.test(_code) && !/["'`]Kalan görev: ?2/.test(_code), "Satırları elle yazma; finished ve tasks.length kullan.");

project_task.starter:
const questions = ["Ay, hangi gezegenin uydusudur?", "Güneş sistemindeki en büyük gezegen hangisidir?"];
const answers = ["Dünya", "Jüpiter"];

// 1) üçüncü soru ve cevabını ekle
// 2) total
// 3) son soruyu ve cevabını yazdır

project_task.solution:
const questions = ["Ay, hangi gezegenin uydusudur?", "Güneş sistemindeki en büyük gezegen hangisidir?"];
const answers = ["Dünya", "Jüpiter"];

// 1) üçüncü soru ve cevabını ekle
questions.push("Kızıl gezegen olarak bilinen gezegen hangisidir?");
answers.push("Mars");
// 2) total
const total = questions.length;
// 3) son soruyu ve cevabını yazdır
console.log(`Soru ${total}: ${questions[total - 1]}`);
console.log(`Cevap: ${answers[total - 1]}`);

check.js:
assert(questions.length === 3 && answers.length === 3, "Her iki dizide de 3 eleman olmalı.");
assert(questions[2] === "Kızıl gezegen olarak bilinen gezegen hangisidir?" && answers[2] === "Mars", "Üçüncü soru ve cevabı (Mars) dizilerin sonuna eklenmeli.");
assert(total === 3, "total 3 olmalı.");
assert(_lines.includes("Soru 3: Kızıl gezegen olarak bilinen gezegen hangisidir?"), "Çıktıda 'Soru 3: Kızıl gezegen olarak bilinen gezegen hangisidir?' görünmeli.");
assert(_lines.includes("Cevap: Mars"), "Çıktıda 'Cevap: Mars' görünmeli.");
assert(!/Soru 3/.test(_code) && !/Cevap: Mars/.test(_code), "Satırları elle yazma; sayı total'dan, metinler dizilerden gelsin.");
